(7529897, 1204035, 50864, '<td valign="top">Lots to think about in this. One of my favorites in the challenge.</td>', 'Lots to think about in this. One of my favorites in the challenge.', '2017-08-20 15:47:26.000000', NULL, 1),
(7529898, 1203874, 50864, '<td valign="top">Nice</td>', 'Nice', '2017-08-20 15:48:08.000000', NULL, 1),
(7529899, 1204040, 50864, '<td valign="top">Well done. Top pick.</td>', 'Well done. Top pick.', '2017-08-20 16:11:07.000000', NULL, 1),
(7529906, 1204040, 173844, '<td valign="top">Campy and surrealistic with an interesting choice of colors, this image is creative and fun.</td>', 'Campy and surrealistic with an interesting choice of colors, this image is creative and fun.', '2017-08-20 17:38:45.000000', NULL, 1),
(7529908, 1204001, 173844, '<td valign="top">I have no idea what this is (okay, there are some faces in there), but it sure engages the eye with its phantasmagoria of swirling and distorted mosaic tile-like pieces.  Reminds me a bit of "Guernica."  Stellar effort.</td>', 'I have no idea what this is (okay, there are some faces in there), but it sure engages the eye with its phantasmagoria of swirling and distorted mosaic tile-like pieces.  Reminds me a bit of "Guernica."  Stellar effort.', '2017-08-20 17:45:43.000000', NULL, 1),
(7529909, 1204038, 173844, '<td valign="top">Fine three dimensional texturing with that beautifully emerging face.  Very creative and artful.  The mood is disturbing, but that''s completely okay.  Elegant and impressive.</td>', 'Fine three dimensional texturing with that beautifully emerging face.  Very creative and artful.  The mood is disturbing, but that''s completely okay.  Elegant and impressive.', '2017-08-20 17:50:47.000000', NULL, 1),
(7529910, 1204037, 173844, '<td valign="top">Very suggestive and magical, as if Mother Nature has more secrets than we''ll ever know.  Terrific fade in color and condition.</td>', 'Very suggestive and magical, as if Mother Nature has more secrets than we''ll ever know.  Terrific fade in color and condition.', '2017-08-20 17:55:17.000000', NULL, 1),
(7529911, 1204032, 173844, '<td valign="top">Moody and romantic, yet not at all saccharine.  It feels like an intimate invitation.  Heady stuff.</td>', 'Moody and romantic, yet not at all saccharine.  It feels like an intimate invitation.  Heady stuff.', '2017-08-20 17:57:45.000000', NULL, 1),
(7529912, 1204027, 173844, '<td valign="top">Straightforward and interesting.  I''m thinking the aftermath of a match with Serena Williams.</td>', 'Straightforward and interesting.  I''m thinking the aftermath of a match with Serena Williams.', '2017-08-20 17:59:17.000000', NULL, 1),
(7529913, 1203762, 173844, '<td valign="top">Cool neon colors in this futuristic feeling image. Perhaps a totem, or simply an interesting design.  I like the spray paint application of the colors and the grounding of the black structure.</td>', 'Cool neon colors in this futuristic feeling image. Perhaps a totem, or simply an interesting design.  I like the spray paint application of the colors and the grounding of the black structure.', '2017-08-20 18:04:50.000000', NULL, 1),
(7529914, 1203874, 173844, '<td valign="top">A story is implied here, but it''s completely open to interpretation, at least to me.  That''s the fun of having a jumping off point without any directions.  Mysterious and enjoyable.</td>', 'A story is implied here, but it''s completely open to interpretation, at least to me.  That''s the fun of having a jumping off point without any directions.  Mysterious and enjoyable.', '2017-08-20 18:09:40.000000', NULL, 1),
(7529915, 1203967, 173844, '<td valign="top">Well done fantasy art with a wonderful sense of place and atmosphere.</td>', 'Well done fantasy art with a wonderful sense of place and atmosphere.', '2017-08-20 18:11:03.000000', NULL, 1),
(7529916, 1204045, 173844, '<td valign="top">Interesting, well done pastiche.</td>', 'Interesting, well done pastiche.', '2017-08-20 18:11:59.000000', NULL, 1),
(7529917, 1203563, 173844, '<td valign="top">Looks like it takes an enormous amount of electricity to power this scintillating image.  The inner workings of a future world, with fabulous colors and compelling imagination.</td>', 'Looks like it takes an enormous amount of electricity to power this scintillating image.  The inner workings of a future world, with fabulous colors and compelling imagination.', '2017-08-20 18:16:44.000000', NULL, 1),
(7529918, 1203999, 173844, '<td valign="top">Interesting design and structure.  Subjectively speaking, the colors are a bit grim for my taste.</td>', 'Interesting design and structure.  Subjectively speaking, the colors are a bit grim for my taste.', '2017-08-20 18:18:35.000000', NULL, 1),
(7529920, 1203454, 173844, '<td valign="top">Usually I don''t appreciate this type of artwork processing, but I like this because of its simplicity and cheerful colors, its peaceful atmosphere, the comfortable frame of the tree.  A pleasure.</td>', 'Usually I don''t appreciate this type of artwork processing, but I like this because of its simplicity and cheerful colors, its peaceful atmosphere, the comfortable frame of the tree.  A pleasure.', '2017-08-20 18:23:53.000000', NULL, 1),
(7529926, 1204046, 103142, '<td valign="top">Hehe! Looks like something that should have been mine. But the editing is much better than I would have done. :)</td>', 'Hehe! Looks like something that should have been mine. But the editing is much better than I would have done. :)', '2017-08-20 21:19:18.000000', NULL, 1),
(7529927, 1204037, 103142, '<td valign="top">Very cool!</td>', 'Very cool!', '2017-08-20 21:19:31.000000', NULL, 1),
