(7529933, 1203967, 94815, '<td valign="top">Beautiful illustrative art.</td>', 'Beautiful illustrative art.', '2017-08-20 22:12:14.000000', NULL, 1),
(7529934, 1204017, 114285, '<td valign="top">This is too wonderful for words!!   I have voted according to whether I would put these images on my wall and this is my favourite by far. My only nitpick is that you cut off his hand, but there could be a reason ;) <br/> <br/>Hope you have kept your original and that it gets the blue, my top pick Jan!!  I''ll congratulate you before hand.</td>', 'This is too wonderful for words!!   I have voted according to whether I would put these images on my wall and this is my favourite by far. My only nitpick is that you cut off his hand, but there could be a reason ;)  Hope you have kept your original and that it gets the blue, my top pick Jan!!  I''ll congratulate you before hand.', '2017-08-20 22:15:27.000000', NULL, 1),
