(7529954, 1204044, 94815, '<td valign="top">Well seen overlay of rectilinear grit and diagonal buildings. Excellent cross-fertilization of visual effects.</td>', 'Well seen overlay of rectilinear grit and diagonal buildings. Excellent cross-fertilization of visual effects.', '2017-08-20 23:09:34.000000', NULL, 1),
(7529955, 1204036, 94815, '<td valign="top">Has a quality of frozen birds in ice like maybe the next earthly environmental calamity.</td>', 'Has a quality of frozen birds in ice like maybe the next earthly environmental calamity.', '2017-08-20 23:22:42.000000', NULL, 1),
